using UnityEngine;
using Flynn.Events;

/// <summary>
/// Pulls an auto-collecting <see cref="WorldItem"/> to the player after a short settle delay, then
/// collects it: resources/items go to the inventory, currencies to their counter. If the inventory
/// has no room the item idles on the ground and re-checks periodically (VS-style gem behaviour).
///
/// Finds the player through a <see cref="PlayerAnchor"/> SO — no FindObjectOfType. Non-auto items
/// (the wrench) disable this component and are picked up with the pickup key instead.
/// </summary>
[RequireComponent(typeof(WorldItem))]
public class DroppedItemMagnet : MonoBehaviour
{
    [SerializeField] private PlayerAnchor _playerAnchor;

    [Header("Timing")]
    [Tooltip("Seconds the drop sits/settles before it may fly to the player.")]
    [SerializeField] private float _settleDelay = 0.6f;
    [Tooltip("How often to re-check for inventory room while waiting.")]
    [SerializeField] private float _roomRecheckInterval = 0.4f;

    [Header("Flight")]
    [SerializeField] private float _maxSpeed = 7f;
    [SerializeField] private float _acceleration = 16f;
    [SerializeField] private float _collectRadius = 0.55f;
    [SerializeField] private float _targetHeight = 0.6f;

    private WorldItem _item;
    private Rigidbody _rb;

    private float _age;
    private float _extraDelay;
    private float _recheckTimer;
    private float _speed;
    private bool _flying;

    /// <summary>
    /// Delay auto-collection by <paramref name="seconds"/> beyond the normal settle (used when the
    /// player drops an item so it doesn't instantly fly back). Takes the longer of any pending delay.
    /// </summary>
    public void Suppress(float seconds)
    {
        _extraDelay = Mathf.Max(_extraDelay, seconds);
        _flying = false;
    }

    private void Awake()
    {
        _item = GetComponent<WorldItem>();
        _rb = GetComponent<Rigidbody>();
    }

    private void OnEnable()
    {
        _age = 0f;
        _extraDelay = 0f;
        _recheckTimer = 0f;
        _speed = 0f;
        _flying = false;
    }

    private void Update()
    {
        ItemDefinition def = _item != null ? _item.Item : null;
        if (def == null) return;

        // Non-auto items (wrench) wait for the pickup key — not our job.
        if (!def.AutoCollects) { enabled = false; return; }

        _age += Time.deltaTime;
        if (_age < _settleDelay + _extraDelay) return;

        Transform player = _playerAnchor != null ? _playerAnchor.Current : null;
        if (player == null) return;

        if (!_flying)
        {
            _recheckTimer -= Time.deltaTime;
            if (_recheckTimer > 0f) return;
            _recheckTimer = _roomRecheckInterval;
            if (!HasRoom(def, player)) return;
            BeginFlight();
        }

        _speed = Mathf.MoveTowards(_speed, _maxSpeed, _acceleration * Time.deltaTime);
        Vector3 target = player.position + Vector3.up * _targetHeight;
        transform.position = Vector3.MoveTowards(transform.position, target, _speed * Time.deltaTime);

        if (Vector3.Distance(transform.position, target) <= _collectRadius)
            Collect(def, player);
    }

    private bool HasRoom(ItemDefinition def, Transform player)
    {
        if (def.isCurrency) return true;
        return PlayerInventory.Instance != null && PlayerInventory.Instance.HasRoomFor(def);
    }

    private void BeginFlight()
    {
        _flying = true;
        if (_rb != null)
        {
            _rb.velocity = Vector3.zero;
            _rb.angularVelocity = Vector3.zero;
            _rb.isKinematic = true; // hand control to the magnet's MoveTowards
        }
    }

    private void Collect(ItemDefinition def, Transform player)
    {
        if (def.isCurrency)
        {
            if (def.currencyTarget != null) def.currencyTarget.Add(_item.Count);
            if (GameEventBus.Instance != null)
                GameEventBus.Instance.Publish(new CurrencyCollected(def, _item.Count));
            Destroy(gameObject);
            return;
        }

        int added = PlayerInventory.Instance != null ? PlayerInventory.Instance.TryAddItem(def, _item.Count) : 0;
        if (added >= _item.Count)
        {
            Destroy(gameObject);
            return;
        }

        // Inventory filled mid-flight: drop the remainder back on the ground and idle.
        if (added > 0) _item.Reduce(added);
        _flying = false;
        _speed = 0f;
        if (_rb != null) _rb.isKinematic = false;
    }
}

using UnityEngine;

/// <summary>
/// Handles the scan interaction flow: holds F to scan a ScanTarget under the cursor.
/// Reads the current ScanTarget from <see cref="PlayerMouseAimer.HoverResult"/> each frame.
/// On key down: validates and calls <see cref="ScanTarget.Begin"/>.
/// While held: calls <see cref="ScanTarget.TickScan"/> and drains battery.
/// On key up or target lost: calls <see cref="ScanTarget.CancelScan"/>.
///
/// The <see cref="WorldInteractTagPresenter"/> already shows the scan progress text
/// by subscribing to <see cref="Flynn.Events.ScanProgressed"/> events.
/// </summary>
[RequireComponent(typeof(PlayerMouseAimer))]
public class PlayerScanController : MonoBehaviour
{
    [Tooltip("Key to hold for scanning.")]
    [SerializeField] private KeyCode _scanKey = KeyCode.F;

    private PlayerMouseAimer _aimer;
    private RobotBattery _battery;
    private ScanTarget _activeTarget;
    private bool _keyHeld;

    private void Awake()
    {
        _aimer = GetComponent<PlayerMouseAimer>();
        _battery = RobotBattery.Instance;
    }

    private void Update()
    {
        bool keyDown = Input.GetKeyDown(_scanKey);
        bool keyUp = Input.GetKeyUp(_scanKey);
        _keyHeld = Input.GetKey(_scanKey);

        var scanTarget = _aimer != null ? _aimer.HoverResult.ScanTarget : null;

        // Start scan on key down
        if (keyDown && scanTarget != null && scanTarget.CanStart())
        {
            _activeTarget = scanTarget;
            _activeTarget.Begin();
        }

        // Tick while held and target is valid
        if (_keyHeld && _activeTarget != null && _activeTarget.IsScanning)
        {
            // Verify target is still the one under cursor
            if (scanTarget != _activeTarget)
            {
                CancelActive();
                return;
            }

            // Check battery
            float costPerSecond = _activeTarget.Config != null
                ? _activeTarget.Config.batteryCostPerSecond : 0f;

            if (costPerSecond > 0f && _battery != null && !_battery.CanSpend(costPerSecond * Time.deltaTime))
            {
                CancelActive();
                return;
            }

            _activeTarget.TickScan(Time.deltaTime);

            if (_battery != null && costPerSecond > 0f)
                _battery.DrainOverTime(costPerSecond);
        }

        // Cancel on key up or target lost
        if (keyUp || (_activeTarget != null && !_activeTarget.IsScanning))
        {
            CancelActive();
        }
    }

    private void CancelActive()
    {
        if (_activeTarget != null && _activeTarget.IsScanning)
            _activeTarget.CancelScan();
        _activeTarget = null;
    }
}

using UnityEngine;
using UnityEngine.UIElements;

/// <summary>
/// Screen-space interaction tag that follows the mouse cursor while an
/// interactable is hovered. Driven by <see cref="WorldInteractTagPresenter"/>
/// when a hover is active the presenter calls <see cref="Show"/> with the
/// prompt text; the tag then follows the cursor each frame until
/// <see cref="HideTag"/> is called.
///
/// Lives as a pre-existing UIDocument under the UI manager so designers can
/// customise the UXML/USS. Uses the Flynn mono palette (black bg, 1px white outline).
/// </summary>
public class InteractTagPanel : UIToolkitPanel
{
    private Label _label;
    private VisualElement _root;

    protected override bool Bind(VisualElement root)
    {
        _root = root.Q<VisualElement>("InteractTagRoot");
        _label = root.Q<Label>("InteractTagLabel");
        return _root != null && _label != null;
    }

    private void LateUpdate()
    {
        if (!IsVisible || _root == null) return;

        var panel = _root.panel;
        if (panel == null) return;

        Vector2 mouse = Input.mousePosition;
        var contentRect = panel.visualTree.layout;
        float scaleX = contentRect.width > 0 ? Screen.width / contentRect.width : 1f;
        float scaleY = contentRect.height > 0 ? Screen.height / contentRect.height : 1f;

        _root.style.left = mouse.x / scaleX;
        _root.style.top = (Screen.height - mouse.y) / scaleY;
